<section id="rezervace"><div class="admin-section-title"><h2>Rezervace</h2><div class="admin-filters"><?php foreach (['all'=>'Všechny'] + STATES as $value=>$label): ?><a class="<?= $filter === $value ? 'selected' : '' ?>" href="/?admin=1&amp;status=<?= e($value) ?>#rezervace"><?= e($label) ?></a><?php endforeach; ?></div></div>
<?php if (!$bookings): ?><div class="empty">V této kategorii zatím nejsou žádné rezervace.</div><?php endif; ?>
<div class="reservation-list"><?php foreach ($bookings as $r): ?><article class="reservation <?= $r['status'] === 'pending' ? 'needs-attention' : '' ?>"><div class="reservation-heading"><div><span class="badge <?= e($r['status']) ?>"><?= e(STATES[$r['status']] ?? $r['status']) ?></span><h3><?= e($r['name']) ?></h3><a href="mailto:<?= e($r['email']) ?>"><?= e($r['email']) ?></a></div><div class="reservation-date"><strong><?= e($r['starts_at'] ? slot_label($r) : ($r['is_individual'] ? 'Individuální domluva' : 'Původní poptávka: ' . $r['requested_date'])) ?></strong><span><?= e($r['package_name']) ?> · <?= e($r['type']) ?> · #<?= (int)$r['id'] ?></span><small>Přijato <?= e(date('j. n. Y H:i', strtotime($r['created_at']))) ?></small></div></div><?php if ($r['note']): ?><p class="client-note"><?= nl2br(e($r['note'])) ?></p><?php endif; ?>
<?php if ($r['status']==='pending'): ?><form method="post" action="/?admin=1" class="quick-actions"><?= csrf_field() ?><input type="hidden" name="action" value="quick_status"><input type="hidden" name="request_id" value="<?= (int)$r['id'] ?>"><?php if ($r['slot_id'] || $r['is_individual']): ?><button class="button" name="status" value="confirmed">✓ Potvrdit rezervaci</button><?php endif; ?><button class="secondary-button" name="status" value="rejected">Zamítnout žádost</button></form><?php endif; ?><form class="reservation-form" method="post" action="/?admin=1"><?= csrf_field() ?><input type="hidden" name="action" value="status"><input type="hidden" name="request_id" value="<?= (int)$r['id'] ?>"><label>Interní poznámka<textarea name="admin_note" maxlength="2000" rows="2"><?= e($r['admin_note']) ?></textarea></label><div class="reservation-actions"><label>Stav rezervace<select name="status"><?php foreach (STATES as $key=>$label): ?><option value="<?= e($key) ?>" <?= $key === $r['status'] ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><button class="button">Uložit stav a poznámku</button></div></form>
<?php if (!$r['is_individual']): ?><details><summary><?= $r['slot_id'] ? 'Přesunout na jiný volný termín' : 'Přiřadit volný termín' ?></summary><?php if (!$freeSlots): ?><p>Nejprve přidejte volný termín.</p><?php else: ?><form method="post" action="/?admin=1" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="assign"><input type="hidden" name="request_id" value="<?= (int)$r['id'] ?>"><label>Nový termín<select name="slot_id" required><?php foreach ($freeSlots as $s): if ((int)$s['package_id'] !== (int)$r['package_id']) continue; ?><option value="<?= (int)$s['id'] ?>"><?= e(slot_label($s)) ?></option><?php endforeach; ?></select></label><button class="secondary-button">Přiřadit a čekat na potvrzení</button></form><?php endif; ?></details><?php endif; ?></article><?php endforeach; ?></div></section>
